message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on pale ground with small tufts of grass under its paws. It has the overall body shape, dense shaggy fur, head and limbs of a brown bear with dark brown fur on the back and legs and lighter tan fur on the underbelly and muzzle, combined with glossy dark reddish-brown chitinous features. A single large curved glossy black horn rises from the center of its forehead, and multiple hard, shiny, segmented plates are embedded in the fur across its back, sides, neck, hips and outer leg joints. A row of six small oval black openings is visible in the light fur on the lower flank beneath the largest side plate. The head has a bear-like snout with a black nose, small dark eyes, and rounded furry ears, and each broad paw bears long pale claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head covered in brown fur with a lighter tan muzzle, black nose at the tip, small dark brown eyes, and a slightly open mouth showing the lower lip",
      "where": "at the front right end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark brown to black horn, smooth and curved upward and backward then forward to a sharp point, with two small tooth-like projections on the inner curve and a thick base set into the fur",
      "where": "centered on the forehead between the ears on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur with slightly darker edges",
      "where": "on top of the head just behind the horn base, one slightly behind the other in side view"
    },
    {
      "part": "legs",
      "looks_like": "four thick heavily furred legs with long shaggy dark brown fur, lighter on the inner and lower chest area",
      "where": "two forelegs under the chest/shoulder and two hind legs under the hips, supporting the body from below"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dark fur and five long curved pale claws on each visible paw",
      "where": "at the bottom ends of the four legs in contact with the ground"
    },
    {
      "part": "plates",
      "looks_like": "multiple hard glossy dark reddish-brown plates with fine pale crack-like segmentation lines and white reflective highlights, varying from small oval to large rectangular and curved collar shapes",
      "where": "embedded in the fur: two small plates on the mid-back, one large rectangular plate on the mid-flank, one large curved plate on the shoulder with a second collar plate on the neck behind it, one large curved plate on the rear hip, and smaller rounded plates on the outer joints of the fore and hind legs"
    },
    {
      "part": "markings",
      "looks_like": "a horizontal row of six small vertically oval black holes with thin pale rims, set in a line",
      "where": "in the light tan fur on the lower side of the torso directly beneath the large mid-flank plate"
    }
  ],
  "attached_objects": [],
  "animals": [
    "brown bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
